'use strict';

// Row parser for the vendor product feed.
//
// The feed is comma separated. The exporter only puts quotes around a field
// when it decided that field needed them, and it pads every row out to the
// width of the widest row in the file.

function unquote(field) {
  const value = field.trim();
  if (value.length >= 2 && value[0] === '"' && value[value.length - 1] === '"') {
    return value.slice(1, value.length - 1);
  }
  return value;
}

// Trailing empties on a row are the padding the exporter adds, not fields the
// vendor actually sent, so they come back off before the row is handed on.
function dropExporterPadding(fields) {
  const out = fields.slice();
  while (out.length > 0 && out[out.length - 1] === '') {
    out.pop();
  }
  return out;
}

// Parses one physical line of the feed into its fields.
function parseRow(line) {
  const text = line === null || line === undefined ? '' : String(line);
  return dropExporterPadding(text.split(',').map(unquote));
}

module.exports = { parseRow };

