'use strict';

const { parseRow } = require('./csv.js');

// Turns a downloaded feed into records keyed by the names in the header row.
function readFeed(text) {
  const source = text === null || text === undefined ? '' : String(text);
  const lines = source.split(/\r?\n/).filter((line) => line !== '');
  if (lines.length === 0) {
    return [];
  }
  const header = parseRow(lines[0]);
  return lines.slice(1).map((line) => {
    const row = parseRow(line);
    const record = {};
    header.forEach((name, i) => {
      record[name] = row[i] === undefined ? '' : row[i];
    });
    return record;
  });
}

module.exports = { readFeed };

