'use strict';
const assert = require('assert');
const { parseRow } = require('./src/csv.js');

let failed = 0;
function check(name, fn) {
  try {
    fn();
    console.log('ok - ' + name);
  } catch (err) {
    failed += 1;
    console.log('FAIL - ' + name + ': ' + err.message);
  }
}

check('a plain row splits on the separators', () => {
  assert.deepStrictEqual(parseRow('sku-1,widget,4'), ['sku-1', 'widget', '4']);
});

check('a quoted field comes back without its quotes', () => {
  assert.deepStrictEqual(parseRow('sku-1,"widget",4'), ['sku-1', 'widget', '4']);
});

check('a separator inside a quoted field stays in the field', () => {
  assert.deepStrictEqual(parseRow('sku-1,"widget, large",4'), ['sku-1', 'widget, large', '4']);
});

if (failed > 0) {
  console.log(failed + ' check(s) failed');
  process.exit(1);
}
console.log('all checks passed');

