'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { parseRow, parseRows } = require('./src/csv.js');
const { readFeed } = require('./src/feed.js');

test('s1 a separator inside a quoted field stays in the field', () => {
  assert.deepStrictEqual(parseRow('sku-1,"widget, large",4'), ['sku-1', 'widget, large', '4']);
  assert.deepStrictEqual(parseRow('"a,b","c,d"'), ['a,b', 'c,d']);
});

test('s2 a doubled quote inside a quoted field becomes one quote', () => {
  assert.deepStrictEqual(parseRow('sku-2,"the ""large"" one",7'), ['sku-2', 'the "large" one', '7']);
  assert.deepStrictEqual(parseRow('"""quoted"""'), ['"quoted"']);
});

test('s3 trailing empty fields are kept', () => {
  assert.deepStrictEqual(parseRow('sku-3,widget,,'), ['sku-3', 'widget', '', '']);
  assert.deepStrictEqual(parseRow('a,,b'), ['a', '', 'b']);
  assert.deepStrictEqual(parseRow('a,b,""'), ['a', 'b', '']);
});

test('s4 records span lines and readFeed follows them', () => {
  assert.deepStrictEqual(
    parseRows('id,note\n1,"line one\nline two"\n2,plain\n'),
    [['id', 'note'], ['1', 'line one\nline two'], ['2', 'plain']]
  );
  assert.deepStrictEqual(parseRows('a,b\r\nc,d\r\n'), [['a', 'b'], ['c', 'd']]);
  assert.deepStrictEqual(
    readFeed('id,note\n1,"line one\nline two"\n'),
    [{ id: '1', note: 'line one\nline two' }]
  );
});

reference_solution.src/csv.js:
'use strict';

// Row parser for the vendor product feed.
//
// The feed is comma separated. A quoted field may contain separators, line
// breaks, and quote characters written as a doubled quote. Every separator
// produces a field, including the empty ones the exporter pads rows with.

function scan(text) {
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  let i = 0;

  while (i < text.length) {
    const ch = text[i];

    if (quoted) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        quoted = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (ch === '"' && field === '') {
      quoted = true;
      i += 1;
      continue;
    }
    if (ch === ',') {
      row.push(field);
      field = '';
      i += 1;
      continue;
    }
    if (ch === '\r' || ch === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      i += ch === '\r' && text[i + 1] === '\n' ? 2 : 1;
      continue;
    }

    field += ch;
    i += 1;
  }

  row.push(field);
  rows.push(row);
  return rows;
}

// Parses one physical line of the feed into its fields.
function parseRow(line) {
  const text = line === null || line === undefined ? '' : String(line);
  return scan(text)[0];
}

// Parses whole feed text into rows. A record ends at a line break that is not
// inside a quoted field; one trailing line break does not start a new record.
function parseRows(text) {
  const source = text === null || text === undefined ? '' : String(text);
  if (source === '') {
    return [];
  }
  const rows = scan(source);
  const last = rows[rows.length - 1];
  if (rows.length > 1 && last.length === 1 && last[0] === '') {
    rows.pop();
  }
  return rows;
}

module.exports = { parseRow, parseRows };

